`timescale 1ns/1ps
module tb;
  reg clk=0, rst_n=0, byte_valid=0; reg [7:0] byte_data=0;
  wire byte_ready, result_valid, err_crc, err_sync; wire [3:0] engine, risk; wire [7:0] confidence, category, flags;
  threat_result_if dut(clk,rst_n,byte_valid,byte_data,byte_ready,engine,risk,confidence,category,flags,result_valid,err_crc,err_sync);
  always #5 clk=~clk; integer fails=0;
  task send(input [7:0] d); begin @(negedge clk); byte_data=d; byte_valid=1; @(negedge clk); byte_valid=0; end endtask
  // Golden frames generated by Python hal.link.encode (see tests / docs): url,high,0.9,phishing ; same with CRC flipped (last byte)
  reg [55:0] good, bad; integer i;
  initial begin
    good = 56'hA50102E60100E8; bad = 56'hA50102E60100E9;
    #20 rst_n=1; #20;
    for (i=6;i>=0;i=i-1) send(good[i*8 +: 8]);
    @(posedge clk); #1;
    if (engine!==1 || risk!==2 || confidence!==8'hE6 || category!==1) begin fails=fails+1; $display("FAIL good frame: e=%0d r=%0d c=%h k=%0d",engine,risk,confidence,category); end
    for (i=6;i>=0;i=i-1) send(bad[i*8 +: 8]);
    #20; if (!err_crc) begin fails=fails+1; $display("FAIL: crc error not flagged"); end
    if (fails==0) $display("TB PASS"); else $display("TB FAILED %0d",fails);
    $finish;
  end
endmodule
